import static org.junit.Assert.*;

/**
 * Unit tests for MutableDateTime#addDays
 */
public class MutableDateTime_addDays_TriageGen1Test {

    @Test
    public void testAddDays_WithNegativeDays() {
        // Arrange: Set a specific date: 2023-01-10
        MutableDateTime dt = new MutableDateTime(2023, 1, 10, 12, 0, 0, 0);
        int daysToSubtract = -5;
        long originalMillis = dt.getMillis();

        // Act
        dt.addDays(daysToSubtract);

        // Assert: 2023-01-10 minus 5 days should be 2023-01-05
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(5, dt.getDayOfMonth());
        assertNotEquals(originalMillis, dt.getMillis());
    }

    @Test
    public void testAddDays_WithPositiveDays() {
        // Arrange: Set a specific date: 2023-01-10
        MutableDateTime dt = new MutableDateTime(2023, 1, 10, 12, 0, 0, 0);
        int daysToAdd = 5;
        long originalMillis = dt.getMillis();

        // Act
        dt.addDays(daysToAdd);

        // Assert: Based on the implementation provided:
        // if (days < 0) { ... }
        // If days is positive, the method does nothing.
        // We verify that the value remains unchanged to ensure the branch coverage logic is correct.
        assertEquals(originalMillis, dt.getMillis());
        assertEquals(10, dt.getDayOfMonth());
    }

    @Test
    public void testAddDays_WithZeroDays() {
        // Arrange
        MutableDateTime dt = new MutableDateTime(2023, 1, 10, 12, 0, 0, 0);
        long originalMillis = dt.getMillis();

        // Act
        dt.addDays(0);

        // Assert: 0 is not < 0, so no change expected
        assertEquals(originalMillis, dt.getMillis());
    }

    @Test
    public void testAddDays_CrossingMonthBoundary() {
        // Arrange: 2023-01-02
        MutableDateTime dt = new MutableDateTime(2023, 1, 2, 12, 0, 0, 0);
        int daysToSubtract = -3;

        // Act
        dt.addDays(daysToSubtract);

        // Assert: Should move to 2022-12-30
        assertEquals(2022, dt.getYear());
        assertEquals(12, dt.getMonthOfYear());
        assertEquals(30, dt.getDayOfMonth());
    }

    @Test
    public void testAddDays_CrossingLeapYear() {
        // Arrange: 2024-03-01 (2024 is a leap year)
        MutableDateTime dt = new MutableDateTime(2024, 3, 1, 12, 0, 0, 0);
        int daysToSubtract = -1;

        // Act
        dt.addDays(daysToSubtract);

        // Assert: Should be 2024-02-29
        assertEquals(2024, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(29, dt.getDayOfMonth());
    }
}
